error NoDirectETH();
error PublicMintLocked();
error ChapterControllerNotSet();

contract BiggiEyesMain2 is ERC721, Ownable, Pausable, ReentrancyGuard {
    using BiggiIdIndexLib for uint256;
    using BiggiIdIndexLib for mapping(uint256 => BiggiIdIndexLib.NFTInfo);
    using SafeERC20 for IERC20;

    address public constant DEV_WALLET = 0x64ADb3e4B5BE8567c599bA8e050F7016C3D51eD0;
    uint256 public constant MAX_BATCH   = 55;
    uint256 public constant MAX_SUPPLY  = 550;

    IBiggiDistributor public distributor;
    IBiggiPriceProvider public priceProvider;
    IBiggiChapterControllerView public chapterController;
    uint256 public chapterId;

    uint16[10] public blockMintCounts;
    BiggiPriceMathLib.BlockInfo[10] public blockInfos;
    uint16[10] public backgroundMintCounts;
    mapping(uint256 => BiggiIdIndexLib.NFTInfo) public nftInfo;
    uint16 public biggiMinted;

    mapping(uint16 => string) public blockBaseURIs;
    string public rewardsBaseURI;
    string public charactersBaseURI;

    IERC20 public BIGGI;
    address public tokenSink;
    uint256 public tokenSinkBps = 10_000;
    uint256 public biggiPerEth  = 1e18;
    address public reserveAddress;

    event URIUpdated(uint8 category, uint16 indexed idx, string uri);
    event DistributorSet(address distributor);
    event PriceProviderSet(address provider);
    event ChapterControllerSet(address indexed controller, uint256 indexed chapterId);
    event BiggiTokenSet(address token);
    event BiggiRateUpdated(uint256 biggiPerEth);
    event TokenSinkUpdated(address sink, uint256 bps);
    event ReserveAddressSet(address indexed oldAddr, address indexed newAddr);
    event PublicMint(address indexed minter, uint256 tokenId, uint256 idx);
    event BlockStatsUpdated(uint16 blk, uint16 blockMinted, uint16 bgMinted);
    event BiggiCollected(address indexed from, uint256 amount, uint256 routedToSink, uint256 forwardedToReserve);
    event BlockPriceUpdated(uint16 indexed blockIdx, uint256 oldPrice, uint256 newPrice);

    uint8 private constant URI_REWARDS    = 0;
    uint8 private constant URI_CHARACTERS = 1;
    uint8 private constant URI_BLOCK      = 2;

    constructor(address initialOwner) ERC721("BiggiEyesPublic", "BIGGI-PUB") Ownable(initialOwner) {
        if (initialOwner == address(0)) revert OwnerZero();
        uint256[10] memory base = [
            uint256(100 ether), 200 ether, 300 ether, 400 ether, 500 ether,
            600 ether, 700 ether, 800 ether, 900 ether, 1000 ether
        ];
        uint256[10] memory growth = [
            uint256(10000), 10000, 10000, 10000, 10000,
            10000, 10000, 10000, 10000, 10000
        ];
        BiggiPriceMathLib.initializeBlocks(blockInfos, base, growth);
    }

    function pause() external onlyOwner { _pause(); }
    function unpause() external onlyOwner { _unpause(); }

    function setDistributor(address dist) external onlyOwner {
        distributor = IBiggiDistributor(dist);
        emit DistributorSet(dist);
    }

    function setPriceProvider(address provider_) external onlyOwner {
        priceProvider = IBiggiPriceProvider(provider_);
        emit PriceProviderSet(provider_);
    }

    function setChapterController(address controller_, uint256 chapterId_) external onlyOwner {
        chapterController = IBiggiChapterControllerView(controller_);
        chapterId = chapterId_;
        emit ChapterControllerSet(controller_, chapterId_);
    }

    function setBiggiToken(address token) external onlyOwner {
        if (token == address(0)) revert BiggiTokenNotSet();
        BIGGI = IERC20(token);
        emit BiggiTokenSet(token);
    }
    function setBiggiRate(uint256 _biggiPerEth) external onlyOwner {
        biggiPerEth = _biggiPerEth;
        emit BiggiRateUpdated(_biggiPerEth);
    }
    function setTokenSink(address sink, uint256 bps) external onlyOwner {
        if (bps > 10000) revert TokenSinkBpsTooHigh();
        tokenSink = sink;
        tokenSinkBps = bps;
        emit TokenSinkUpdated(sink, bps);
    }

    function setReserveAddress(address _reserve) external onlyOwner {
        emit ReserveAddressSet(reserveAddress, _reserve);
        reserveAddress = _reserve;
    }

    function setBlockCurrentPrice(uint16 blockIdx, uint256 newPrice) external onlyOwner {
        if (blockIdx < 1 || blockIdx > 10) revert InvalidBlock();
        uint256 old = blockInfos[blockIdx - 1].currentPrice;
        blockInfos[blockIdx - 1].currentPrice = newPrice;
        emit BlockPriceUpdated(blockIdx, old, newPrice);
    }

    function setURI(uint8 category, uint16 idx, string calldata uri) external onlyOwner {
        if (category == URI_REWARDS) {
            rewardsBaseURI = uri;
        } else if (category == URI_CHARACTERS) {
            charactersBaseURI = uri;
        } else if (category == URI_BLOCK) {
            if (idx < 1 || idx > 10) revert InvalidBlock();
            blockBaseURIs[idx] = uri;
        } else {
            revert InvalidCategory();
        }
        emit URIUpdated(category, idx, uri);
    }

    function tokenURI(uint256 tokenId) public view override returns (string memory) {
        if (!exists(tokenId)) revert NoToken();
        if (tokenId >= BiggiIdIndexLib.BIGGI_OFFSET && tokenId < BiggiIdIndexLib.CHARACTER_OFFSET) {
            uint256 idx = BiggiIdIndexLib.nftIndexFromTokenId(tokenId);
            BiggiIdIndexLib.NFTInfo memory info = nftInfo[idx];
            return BiggiMetaRedeemLib.buildNftUri(
                blockBaseURIs[info.blockIdx], info.mainId,
                BiggiNamesLib2.blockName(info.blockIdx), BiggiNamesLib2.backgroundShort(info.background)
            );
        }
        if (tokenId >= BiggiIdIndexLib.CHARACTER_OFFSET && tokenId < BiggiIdIndexLib.CHARACTER_OFFSET + 10) {
            string memory charFile = string.concat(
                "Biggi_", Strings.toString(tokenId - BiggiIdIndexLib.CHARACTER_OFFSET + 110),
                "_REWARD.json"
            );
            return string.concat(charactersBaseURI, charFile);
        }
        revert InvalidIndex();
    }

    function exists(uint256 tokenId) public view returns (bool) { return _ownerOf(tokenId) != address(0); }

    function blockOf(uint256 tokenId) external view returns (uint16) {
        if (tokenId < BiggiIdIndexLib.BIGGI_OFFSET) return 0;
        if (!exists(tokenId)) return 0;
        uint256 idx = BiggiIdIndexLib.nftIndexFromTokenId(tokenId);
        return nftInfo[idx].blockIdx;
    }

    function _requirePublicUnlocked() internal view {
        if (address(chapterController) == address(0)) revert ChapterControllerNotSet();
        if (!chapterController.isPublicMintUnlocked(chapterId)) revert PublicMintLocked();
    }

    function getCurrentBlockPrice(uint16 blockIdx) public view returns (uint256) {
        if (blockIdx < 1 || blockIdx > 10) revert InvalidBlock();

        address provider = address(0);
        if (address(chapterController) != address(0)) {
            provider = chapterController.getChapterPriceProvider(chapterId);
        }
        if (provider == address(0)) {
            provider = address(priceProvider);
        }
        if (provider == address(0)) {
            return blockInfos[blockIdx - 1].currentPrice;
        }
        return IBiggiPriceProvider(provider).getCurrentBlockPrice(blockIdx);
    }

    function getBlockMintCount(uint16 blockIdx) public view returns (uint16) {
        if (blockIdx < 1 || blockIdx > 10) revert InvalidBlock();
        return blockMintCounts[blockIdx - 1];
    }

    function getMintData(uint256 index) external view returns (uint256, uint256, uint256) {
        BiggiIdIndexLib.NFTInfo memory info = nftInfo[index];
        return (info.ticketPrice, info.blockPrice, info.finalPrice);
    }

    function findUnsetIndices() external view returns (uint256[] memory) {
        return nftInfo.findUnsetIndices(MAX_SUPPLY);
    }

    function batchSetNFTBackgroundAndBlock(
        uint256[] calldata indices,
        uint16[] calldata bgCodes,
        uint16[] calldata blockIndices,
        uint256[] calldata mainIds
    ) external onlyOwner {
        uint256 len = indices.length;
        if (len > MAX_BATCH) revert InvalidIndex();
        if (!(len == bgCodes.length && len == blockIndices.length && len == mainIds.length)) revert InvalidIndex();

        for (uint256 i = 0; i < len; ++i) {
            uint256 idx = indices[i];
            if (idx < 1 || idx > MAX_SUPPLY) revert InvalidIndex();
            if (bgCodes[i] < 1 || bgCodes[i] > 10) revert InvalidBg();
            if (blockIndices[i] < 1 || blockIndices[i] > 10) revert InvalidBlock();

            BiggiIdIndexLib.NFTInfo storage info = nftInfo[idx];
            if (info.minted || info.background != 0 || info.blockIdx != 0 || info.mainId != 0) revert AlreadySet();

            info.background = bgCodes[i];
            info.blockIdx   = blockIndices[i];
            info.mainId     = mainIds[i];
        }
    }

    function mintPublic(uint256 idx) external payable nonReentrant whenNotPaused {
        _requirePublicUnlocked();
        if (idx < 1 || idx > MAX_SUPPLY) revert InvalidIndex();
        if (nftInfo[idx].minted) revert InvalidIndex();
        BiggiIdIndexLib.NFTInfo storage info = nftInfo[idx];
        if (info.background == 0 || info.blockIdx == 0) revert InvalidIndex();
        if (biggiMinted >= MAX_SUPPLY) revert AllNFTsMintedErr();

        uint16 blk_ = info.blockIdx;
        uint256 price = getCurrentBlockPrice(blk_);
        if (msg.value < price) revert InsufficientPayment();

        _splitAndForwardAmount(price);

        uint256 overpay = msg.value - price;
        if (overpay > 0) {
            (bool rf, ) = msg.sender.call{value: overpay}("");
            require(rf, "refund failed");
        }

        _finalizePublicMint(msg.sender, idx, blk_, info.background, price);
    }

    function mintPublicWithBiggi(uint256 idx) external nonReentrant whenNotPaused {
        _requirePublicUnlocked();
        if (idx < 1 || idx > MAX_SUPPLY) revert InvalidIndex();
        if (nftInfo[idx].minted) revert InvalidIndex();
        BiggiIdIndexLib.NFTInfo storage info = nftInfo[idx];
        if (info.background == 0 || info.blockIdx == 0) revert InvalidIndex();
        if (biggiMinted >= MAX_SUPPLY) revert AllNFTsMintedErr();

        uint16 blk_ = info.blockIdx;
        uint256 price = getCurrentBlockPrice(blk_);
        if (address(BIGGI) == address(0)) revert BiggiTokenNotSet();

        uint256 tokenAmount = _ethToBiggi(price);
        _collectBiggi(msg.sender, tokenAmount);
        _finalizePublicMint(msg.sender, idx, blk_, info.background, price);
    }

    function _finalizePublicMint(address to, uint256 idx, uint16 blk_, uint16 bg_, uint256 price) internal {
        BiggiIdIndexLib.NFTInfo storage info = nftInfo[idx];
        info.minted = true;
        unchecked { biggiMinted++; }

        uint256 tokenId = BiggiIdIndexLib.tokenIdFromNftIndex(idx);
        _safeMint(to, tokenId);

        unchecked {
            blockMintCounts[blk_ - 1]++;
            backgroundMintCounts[bg_ - 1]++;
        }

        info.ticketPrice = 0;
        info.blockPrice  = price;
        info.finalPrice  = price;

        emit PublicMint(to, tokenId, idx);
        emit BlockStatsUpdated(blk_, blockMintCounts[blk_ - 1], backgroundMintCounts[bg_ - 1]);
    }

    function _ethToBiggi(uint256 ethAmount) internal view returns (uint256) {
        return (ethAmount * biggiPerEth) / 1e18;
    }

    function _collectBiggi(address from, uint256 amount) internal {
        if (address(BIGGI) == address(0)) revert BiggiTokenNotSet();
        BIGGI.safeTransferFrom(from, address(this), amount);

        uint256 routed = 0;
        if (tokenSink != address(0) && tokenSinkBps > 0) {
            routed = (amount * tokenSinkBps) / 10000;
            if (routed > 0) BIGGI.safeTransfer(tokenSink, routed);
        }

        uint256 toReserve = amount - routed;
        if (toReserve > 0) {
            if (reserveAddress == address(0)) revert InvalidReserve();
            BIGGI.safeTransfer(reserveAddress, toReserve);
            try IBiggiReserve(reserveAddress).notifyBiggiReceived(toReserve) {
            } catch {
            }
        }

        emit BiggiCollected(from, amount, routed, toReserve);
    }

    function _splitAndForwardAmount(uint256 amount) internal {
        require(amount > 0, "zero amount");
        uint256 toDistributor = (amount * 6000) / 10000;
        if (address(distributor) != address(0) && toDistributor > 0) {
            (bool okD, ) = address(distributor).call{value: toDistributor}(
                abi.encodeWithSelector(IBiggiDistributor.receiveMintShare.selector)
            );
            require(okD, "distributor fwd failed");
        } else {
            (bool sDev, ) = DEV_WALLET.call{value: amount}("");
            require(sDev, "dev send failed");
            return;
        }
        uint256 devPart = amount - toDistributor;
        (bool sent, ) = DEV_WALLET.call{value: devPart}("");
        if (!sent) revert DevPaymentFailed();
    }

    function getBackgroundMintCount(uint16 bg) external view returns (uint16) {
        if (bg < 1 || bg > 10) revert InvalidBg();
        return backgroundMintCounts[bg - 1];
    }

    function rescueERC20(address token, address to, uint256 amount) external onlyOwner {
        IERC20(token).safeTransfer(to, amount);
    }
    function rescueNative(address payable to, uint256 amount) external onlyOwner {
        (bool ok, ) = to.call{value: amount}("");
        require(ok, "native rescue failed");
    }

    receive() external payable { revert NoDirectETH(); }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

/*
 MultiCollectionDistributor - chapter-aware refactor

 Zachováno:
 - pevné split BPS
 - whitelist callerů
 - forwarding přes receiveMintShare()
 - pending retry mechanismus

 Přidáno:
 - optional registry-based chapter attribution
 - accounting per series/chapter/source collection
*/

import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";

import "./Library/BiggiBpsLib.sol";

interface IBiggiSeriesRegistryDistributor {
    function chapterByCollection(address collection) external view returns (uint256);
    function getChapterMeta(uint256 chapterId) external view returns (uint256 seriesId, uint256 chapterNumber);
}

contract BiggiMultiCollectionDistributor is Ownable, ReentrancyGuard, Pausable {
    address public collectionRewards;
    address public reserve;
    address public buybackAgent;
    address public treasury;
    address public communityCenter;
    address public registry;

    mapping(address => bool) public collections;

    mapping(address => uint256) public pending;
    uint256 public totalPending;

    uint256 public totalReceived;
    mapping(address => uint256) public receivedByCollection;
    mapping(uint256 => uint256) public receivedBySeries;
    mapping(uint256 => uint256) public receivedByChapter;

    bytes4 private constant RECV_SELECTOR = bytes4(keccak256("receiveMintShare()"));

    event CollectionAdded(address indexed coll);
    event CollectionRemoved(address indexed coll);
    event RecipientSet(string indexed name, address indexed oldAddr, address indexed newAddr);
    event RegistrySet(address indexed oldRegistry, address indexed newRegistry);
    event MintShareReceived(address indexed collection, uint256 amount);
    event ChapterAttributed(address indexed source, uint256 indexed seriesId, uint256 indexed chapterId, uint256 amount);
    event ForwardSucceeded(address indexed recipient, uint256 amount);
    event ForwardFailed(address indexed recipient, uint256 amount);
    event PendingRetried(address indexed recipient, uint256 amount, bool success);
    event PendingPartiallyRetried(address indexed recipient, uint256 amount, bool success);
    event PendingWithdrawn(address indexed to, uint256 amount);
    event TreasuryRemainderHandled(uint256 remainder);

    modifier onlyWhitelisted() {
        require(collections[msg.sender], "Distributor: caller not whitelisted");
        _;
    }

    constructor(address initialOwner) Ownable(initialOwner) {}

    function addCollection(address coll) external onlyOwner {
        require(coll != address(0), "zero");
        collections[coll] = true;
        emit CollectionAdded(coll);
    }

    function removeCollection(address coll) external onlyOwner {
        require(coll != address(0), "zero");
        collections[coll] = false;
        emit CollectionRemoved(coll);
    }

    function setRegistry(address registry_) external onlyOwner {
        emit RegistrySet(registry, registry_);
        registry = registry_;
    }

    function setCollectionRewards(address addr) external onlyOwner {
        emit RecipientSet("collectionRewards", collectionRewards, addr);
        collectionRewards = addr;
    }
    function setReserve(address addr) external onlyOwner {
        emit RecipientSet("reserve", reserve, addr);
        reserve = addr;
    }
    function setBuybackAgent(address addr) external onlyOwner {
        emit RecipientSet("buybackAgent", buybackAgent, addr);
        buybackAgent = addr;
    }
    function setTreasury(address addr) external onlyOwner {
        emit RecipientSet("treasury", treasury, addr);
        treasury = addr;
    }
    function setCommunityCenter(address addr) external onlyOwner {
        emit RecipientSet("communityCenter", communityCenter, addr);
        communityCenter = addr;
    }

    function distribute() external payable nonReentrant whenNotPaused onlyWhitelisted {
        _distributeFrom(msg.sender, msg.value);
    }

    function receiveMintShare() external payable nonReentrant whenNotPaused {
        require(collections[msg.sender], "Distributor: caller not whitelisted");
        _distributeFrom(msg.sender, msg.value);
    }

    function _distributeFrom(address collection, uint256 value) internal {
        require(value > 0, "no value");
        require(
            collectionRewards != address(0) &&
            reserve != address(0) &&
            buybackAgent != address(0) &&
            treasury != address(0) &&
            communityCenter != address(0),
            "recips not set"
        );

        totalReceived += value;
        receivedByCollection[collection] += value;
        _recordChapterAttribution(collection, value);
        emit MintShareReceived(collection, value);

        uint256 shareCollection = BiggiBpsLib.part(value, BiggiBpsLib.DIST_COLLECTION_BPS);
        uint256 shareReserve    = BiggiBpsLib.part(value, BiggiBpsLib.DIST_RESERVE_BPS);
        uint256 shareBuyback    = BiggiBpsLib.part(value, BiggiBpsLib.DIST_BUYBACK_BPS);
        uint256 shareTreasury   = BiggiBpsLib.part(value, BiggiBpsLib.DIST_TREASURY_BPS);
        uint256 shareCommunity  = BiggiBpsLib.part(value, BiggiBpsLib.DIST_COMMUNITY_BPS);

        uint256 sumShares = shareCollection + shareReserve + shareBuyback + shareTreasury + shareCommunity;
        if (value > sumShares) {
            uint256 remainder = value - sumShares;
            shareTreasury += remainder;
            emit TreasuryRemainderHandled(remainder);
        }

        _tryForwardWithFunc(collectionRewards, shareCollection);
        _tryForwardWithFunc(reserve, shareReserve);
        _tryForwardWithFunc(buybackAgent, shareBuyback);
        _tryForwardWithFunc(treasury, shareTreasury);
        _tryForwardWithFunc(communityCenter, shareCommunity);
    }

    function _recordChapterAttribution(address source, uint256 amount) internal {
        if (registry == address(0)) return;
        uint256 chapterId = IBiggiSeriesRegistryDistributor(registry).chapterByCollection(source);
        if (chapterId == 0) return;
        (uint256 seriesId, ) = IBiggiSeriesRegistryDistributor(registry).getChapterMeta(chapterId);
        receivedByChapter[chapterId] += amount;
        receivedBySeries[seriesId] += amount;
        emit ChapterAttributed(source, seriesId, chapterId, amount);
    }

    function _tryForwardWithFunc(address recipient, uint256 amt) internal {
        if (amt == 0) return;
        bytes memory payload = abi.encodeWithSelector(RECV_SELECTOR);
        (bool ok, ) = recipient.call{value: amt}(payload);
        if (ok) {
            emit ForwardSucceeded(recipient, amt);
        } else {
            pending[recipient] += amt;
            totalPending += amt;
            emit ForwardFailed(recipient, amt);
        }
    }

    function retryPending(address recipient) external onlyOwner nonReentrant {
        uint256 amt = pending[recipient];
        require(amt > 0, "no pending");

        pending[recipient] = 0;
        totalPending -= amt;

        bytes memory payload = abi.encodeWithSelector(RECV_SELECTOR);
        (bool ok, ) = recipient.call{value: amt}(payload);

        if (ok) {
            emit PendingRetried(recipient, amt, true);
        } else {
            pending[recipient] = amt;
            totalPending += amt;
            emit PendingRetried(recipient, amt, false);
        }
    }

    function retryPendingAmount(address recipient, uint256 amount) external onlyOwner nonReentrant {
        require(amount > 0, "zero amount");
        uint256 available = pending[recipient];
        require(available >= amount, "not enough pending");

        pending[recipient] = available - amount;
        totalPending -= amount;

        bytes memory payload = abi.encodeWithSelector(RECV_SELECTOR);
        (bool ok, ) = recipient.call{value: amount}(payload);

        if (ok) {
            emit PendingPartiallyRetried(recipient, amount, true);
        } else {
            pending[recipient] = available;
            totalPending += amount;
            emit PendingPartiallyRetried(recipient, amount, false);
        }
    }

    function withdrawEther(address payable to, uint256 amount) external onlyOwner nonReentrant {
        require(to != address(0), "to0");
        uint256 freeBal = address(this).balance - totalPending;
        require(amount <= freeBal, "insufficient free balance");
        (bool ok, ) = to.call{value: amount}("");
        require(ok, "withdraw failed");
        emit PendingWithdrawn(to, amount);
    }

    function pendingOf(address recipient) external view returns (uint256) {
        return pending[recipient];
    }

    function pause() external onlyOwner { _pause(); }
    function unpause() external onlyOwner { _unpause(); }

    receive() external payable {}
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

/*
  BiggiNFTRewards.sol
  - ERC721 reward contract that mints reward NFTs on claim.
  - Supports: Character(last-mint) rewards (onlyMainContract), Manual admin rewards (owner),
    Mystery events (eligible address list + Chainlink VRF via vrfRouter).
  - Metadata (tokenURI) are provided by owner on event creation (IPFS URIs).
*/

import "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

interface IBiggiSeriesRegistryRewards {
    function isCollectionRewardsCollection(address collection) external view returns (bool);
}

interface IRewardVRFRouter {
    // Minimal expected router API — must return requestId which will be forwarded back
    function requestRandomForReward(address requester, uint256 eventId) external returns (uint256 requestId);
}

contract BiggiNFTRewards is ERC721, Ownable, ReentrancyGuard {
    /* ===== Types ===== */
    enum EventKind { Undefined, Character, Manual, Mystery }

    struct RewardEvent {
        EventKind kind;
        address creator;        // who created the event (owner or main)
        uint256 rewardStartId;  // first rewardId for this event
        uint256 rewardCount;    // how many reward entries
        bool randomnessRequested;
        bool finished;
        uint256 vrfRequestId;   // if randomness requested
    }

    /* ===== State ===== */
    uint256 public nextRewardId = 1; // rewardId == tokenId when minted
    uint256 public nextEventId = 1;

    mapping(uint256 => RewardEvent) public events; // eventId => event
    mapping(uint256 => string) public rewardTokenUri; // rewardId => tokenUri (IPFS)
    mapping(uint256 => address) public assignedTo;    // rewardId => assigned address (0 = unassigned)
    mapping(uint256 => bool) public claimed;          // rewardId => claimed

    // Mystery event eligible lists
    mapping(uint256 => address[]) private eventEligible; // eventId => list of eligible addresses

    // Map vrfRequestId => eventId
    mapping(uint256 => uint256) public vrfRequestToEvent;

    // Access-controlled roles
    address public mainContract; // primární / legacy VRF collection
    address public vrfRouter;
    address public registry;
    mapping(address => bool) public allowedMainCollections;

    /* ===== Events ===== */
    event RewardEventCreated(uint256 indexed eventId, EventKind kind, uint256 startRewardId, uint256 count, address indexed creator);
    event RewardAssigned(uint256 indexed rewardId, address indexed to);
    event RewardClaimed(uint256 indexed rewardId, address indexed claimer, uint256 tokenId);
    event MysteryRandomRequested(uint256 indexed eventId, uint256 indexed requestId);
    event MysteryRandomFulfilled(uint256 indexed eventId, uint256 indexed requestId, uint256 random);
    event RegistrySet(address indexed oldRegistry, address indexed newRegistry);
    event MainCollectionApprovalSet(address indexed collection, bool approved);

    /* ===== Modifiers ===== */
    modifier onlyApprovedMainCollection() {
        require(_isApprovedMainCollection(msg.sender), "only approved main");
        _;
    }
    modifier onlyVrfRouter() {
        require(msg.sender == vrfRouter, "only vrf router");
        _;
    }

    constructor(address _owner) 
        ERC721("Biggi Reward", "BGR")
        Ownable(_owner)
    {
        require(_owner != address(0), "owner0");
        // _transferOwnership(_owner) se již volá v Ownable konstruktoru
    }

    /* ===== Admin: set external contracts ===== */
    function setMainContract(address m) external onlyOwner {
        mainContract = m;
        if (m != address(0)) {
            allowedMainCollections[m] = true;
            emit MainCollectionApprovalSet(m, true);
        }
    }
    function setVrfRouter(address r) external onlyOwner {
        vrfRouter = r;
    }
    function setRegistry(address registry_) external onlyOwner {
        emit RegistrySet(registry, registry_);
        registry = registry_;
    }
    function setAllowedMainCollection(address collection, bool approved) external onlyOwner {
        require(collection != address(0), "collection0");
        allowedMainCollections[collection] = approved;
        emit MainCollectionApprovalSet(collection, approved);
    }

    function _isApprovedMainCollection(address collection) internal view returns (bool) {
        if (collection == mainContract && collection != address(0)) return true;
        if (allowedMainCollections[collection]) return true;
        if (registry != address(0)) {
            return IBiggiSeriesRegistryRewards(registry).isCollectionRewardsCollection(collection);
        }
        return false;
    }

    /* ===== Event creation helpers =====
       - tokenUris: array of IPFS URIs (length = rewardCount).
       - eligible: for Mystery events, array of eligible addresses (may contain duplicates — deduped on selection).
       - For Character / Manual: supply tokenUris length == 1 and either eligible = [winner] (or assigned by call).
    */

    // Owner creates manual reward and directly assigns winner (creator can be owner)
    function createManualReward(address winner, string calldata tokenUri) external onlyOwner returns (uint256 eventId, uint256 rewardId) {
        require(winner != address(0), "winner0");
        // create event with single reward
        eventId = nextEventId++;
        rewardId = nextRewardId++;

        events[eventId] = RewardEvent({
            kind: EventKind.Manual,
            creator: msg.sender,
            rewardStartId: rewardId,
            rewardCount: 1,
            randomnessRequested: false,
            finished: false,
            vrfRequestId: 0
        });

        rewardTokenUri[rewardId] = tokenUri;
        assignedTo[rewardId] = winner;

        emit RewardEventCreated(eventId, EventKind.Manual, rewardId, 1, msg.sender);
        emit RewardAssigned(rewardId, winner);
    }

    // Main contract notifies of last-mint in block; only mainContract can call
    // Supply the IPFS tokenUri for the reward (owner/main must prepare it)
    function createCharacterReward(address winner, string calldata tokenUri) external onlyApprovedMainCollection returns (uint256 eventId, uint256 rewardId) {
        require(winner != address(0), "winner0");
        eventId = nextEventId++;
        rewardId = nextRewardId++;

        events[eventId] = RewardEvent({
            kind: EventKind.Character,
            creator: msg.sender,
            rewardStartId: rewardId,
            rewardCount: 1,
            randomnessRequested: false,
            finished: false,
            vrfRequestId: 0
        });

        rewardTokenUri[rewardId] = tokenUri;
        assignedTo[rewardId] = winner;

        emit RewardEventCreated(eventId, EventKind.Character, rewardId, 1, msg.sender);
        emit RewardAssigned(rewardId, winner);
    }

    // Owner creates a mystery event: provide tokenUris[] (length = winnersCount) and eligible addresses.
    function createMysteryEvent(string[] calldata tokenUris, address[] calldata eligible) external onlyOwner returns (uint256 eventId) {
        require(tokenUris.length > 0, "no tokens");
        require(eligible.length > 0, "no eligible");

        eventId = nextEventId++;
        uint256 startId = nextRewardId;
        uint256 cnt = tokenUris.length;
        // reserve rewardIds
        for (uint256 i = 0; i < cnt; ++i) {
            rewardTokenUri[nextRewardId] = tokenUris[i];
            nextRewardId++;
        }

        events[eventId] = RewardEvent({
            kind: EventKind.Mystery,
            creator: msg.sender,
            rewardStartId: startId,
            rewardCount: cnt,
            randomnessRequested: false,
            finished: false,
            vrfRequestId: 0
        });

        // store eligible list
        for (uint256 i = 0; i < eligible.length; ++i) {
            eventEligible[eventId].push(eligible[i]);
        }

        emit RewardEventCreated(eventId, EventKind.Mystery, startId, cnt, msg.sender);
    }

    // Owner (or later we could allow main) requests randomness for mystery event
    // This forwards to vrfRouter; vrfRouter must call back fulfillRandom.
    function requestMysteryRandom(uint256 eventId) external onlyOwner returns (uint256 requestId) {
        RewardEvent storage ev = events[eventId];
        require(ev.kind == EventKind.Mystery, "not mystery");
        require(!ev.randomnessRequested, "already requested");
        require(vrfRouter != address(0), "vrf router not set");

        // call vrfRouter
        requestId = IRewardVRFRouter(vrfRouter).requestRandomForReward(address(this), eventId);
        ev.randomnessRequested = true;
        ev.vrfRequestId = requestId;
        vrfRequestToEvent[requestId] = eventId;

        emit MysteryRandomRequested(eventId, requestId);
    }

    // VRF router (trusted) calls this to deliver randomness.
    // We pick unique winners from eligible list and assign them to reserved rewardIds (in order).
    function fulfillRandom(uint256 requestId, uint256 random) external onlyVrfRouter {
        uint256 eventId = vrfRequestToEvent[requestId];
        require(eventId != 0, "bad request");

        RewardEvent storage ev = events[eventId];
        require(ev.kind == EventKind.Mystery, "not mystery");
        require(ev.randomnessRequested, "not requested");
        require(!ev.finished, "already finished");

        address[] storage pool = eventEligible[eventId];
        uint256 poolSize = pool.length;
        require(poolSize > 0, "empty pool");

        uint256 winnersNeeded = ev.rewardCount;
        require(winnersNeeded <= poolSize, "not enough eligible");

        // pick unique winners using Fisher-Yates-ish deterministic selection based on random seed
        // selectedIndices mapping not stored, we simply mark picked via swapping in a temp array copy
        address[] memory temp = new address[](poolSize);
        for (uint256 i = 0; i < poolSize; ++i) temp[i] = pool[i];

        uint256 seed = random;
        uint256 startId = ev.rewardStartId;
        uint256 assignedCount = 0;
        for (uint256 k = 0; k < winnersNeeded; ++k) {
            // pick index
            uint256 idx = seed % (poolSize - k);
            address winner = temp[idx];

            // assign rewardId
            uint256 rid = startId + k;
            assignedTo[rid] = winner;
            emit RewardAssigned(rid, winner);
            assignedCount++;

            // swap chosen with last unchosen
            temp[idx] = temp[poolSize - 1 - k];

            // update seed for next pick
            seed = uint256(keccak256(abi.encodePacked(seed, k, winner, block.timestamp)));
        }

        ev.finished = true;

        emit MysteryRandomFulfilled(eventId, requestId, random);
    }

    /* ===== Claim function =====
       - claimer must match assignedTo[rewardId]
       - mints ERC721 tokenId == rewardId to claimer with tokenURI as stored
    */
    function claim(uint256 rewardId) external nonReentrant {
        require(assignedTo[rewardId] == msg.sender, "not assigned");
        require(!claimed[rewardId], "already claimed");

        claimed[rewardId] = true;
        _safeMint(msg.sender, rewardId);
        // we override tokenURI via tokenURI() below using rewardTokenUri mapping
        emit RewardClaimed(rewardId, msg.sender, rewardId);
    }

    /* ===== Views & helpers ===== */

    function rewardInfo(uint256 rewardId) external view returns (address assigned, bool isClaimed, string memory uri) {
        assigned = assignedTo[rewardId];
        isClaimed = claimed[rewardId];
        uri = rewardTokenUri[rewardId];
    }

    function eventEligibleCount(uint256 eventId) external view returns (uint256) {
        return eventEligible[eventId].length;
    }

    function getEligibleAt(uint256 eventId, uint256 idx) external view returns (address) {
        return eventEligible[eventId][idx];
    }

    /* ===== tokenURI override to read from mapping ===== */
    function tokenURI(uint256 tokenId) public view override returns (string memory) {
        require(_ownerOf(tokenId) != address(0), "ERC721: invalid token ID");
        string memory uri = rewardTokenUri[tokenId];
        return uri;
    }

    /* ===== Admin rescue (owner only) ===== */
    // In case some tokenUri was set in error, owner cannot reassign reward assignedTo — we keep immutability as requested.
    // Admin can burn unclaimed rewards by marking them finished/unassigned if needed (not implemented — you said non-revokable).

    /* ===== Misc ===== */
    receive() external payable { } // allow receiving fee-less ETH (not used here)
}

