    uint256 internal constant BPS_DENOM = 10_000;

    // Mint split (overall)
    uint256 internal constant DEV_BPS         = 4000; // 40%
    uint256 internal constant DISTRIBUTOR_BPS = 6000; // 60%

    // Distributor split (from the 60%)
