    uint256 internal constant TREASURY_TO_REWARDS_BPS = 5000; // 50%
    // remaining 50% stays in Treasury

    function part(uint256 amount, uint256 bps) internal pure returns (uint256) {
        return (amount * bps) / BPS_DENOM;
    }
}

