pragma solidity ^0.8.24;

import "@openzeppelin/contracts/access/Ownable.sol";

interface IBiggiBuybackAgent {
    function setRouter(address router_) external;
    function setTreasury(address treasury_) external;
    function setPolicy(address policy_) external;
    function setDripLM(address dripLM_) external;
    function setSwapPath(address[] calldata newPath) external;
    function clearSwapPath() external;
    function setFallbacks(uint256 slipBps, uint256 deadlineSec, uint256 cooldownSec) external;
    function toggleAutoBuyback(bool enabled) external;
}

interface IBiggiDripLiquidityManager {
    function setRouter(address r) external;
    function setReserve(address r) external;
    function setDripDistributor(address d) external;
    function setBuybackAgent(address a) external;
    function setSellPct(uint8 pct) external;
    function setSlippageBps(uint256 bps) external;
    function setTxDeadlineSec(uint256 sec_) external;
}

interface IDripDistributorSetup {
    function setDripLM(address lm) external;
    function setTreasury(address t) external;
    function setTokensPerMint(uint256 v) external;
    function setCollection(address coll, bool allowed) external;
}

interface IBiggiTokenSupplySetup {
    function setSupplyController(address c) external;
}

interface IBiggiSupplyControllerSetup {
    function setPair(address pair_) external;
    function snapshotBaseline() external;
}

contract BiggiBuybackDripSetup is Ownable {
    address public immutable buybackAgent;
    address public immutable dripLM;
    address public immutable dripDistributor;
    address public immutable reserveAddr;
    address public immutable treasuryAddr;
    address public immutable routerAddr;
    address public immutable policyAddr;

    address public tokenAddr;
    address public supplyController;
    bool public executed;

    event BranchSetupExecuted(address indexed buybackAgent, address indexed dripLM, address indexed dripDistributor);
    event SupplyTargetsSet(address indexed token, address indexed supplyController);
    event SupplyControllerWired(address indexed token, address indexed supplyController);
    event SupplyControllerPairConfigured(address indexed pair, bool baselineSnapshotted);

    constructor(address initialOwner,address buybackAgent_,address dripLM_,address dripDistributor_,address reserveAddr_,address treasuryAddr_,address routerAddr_,address policyAddr_) Ownable(initialOwner) {
        require(initialOwner != address(0), "owner=0");
        require(buybackAgent_ != address(0), "buyback=0");
        require(dripLM_ != address(0), "dripLM=0");
        require(dripDistributor_ != address(0), "dripD=0");
        require(reserveAddr_ != address(0), "reserve=0");
        require(treasuryAddr_ != address(0), "treasury=0");
        require(routerAddr_ != address(0), "router=0");
        buybackAgent = buybackAgent_; dripLM = dripLM_; dripDistributor = dripDistributor_; reserveAddr = reserveAddr_; treasuryAddr = treasuryAddr_; routerAddr = routerAddr_; policyAddr = policyAddr_;
    }

    function setupBuybackCore() public onlyOwner {
        IBiggiBuybackAgent B = IBiggiBuybackAgent(buybackAgent);
        B.setRouter(routerAddr);
        B.setTreasury(treasuryAddr);
        B.setPolicy(policyAddr);
        B.setDripLM(dripLM);
    }

    function configureBuybackSwapAndFallbacks(address[] calldata path,uint256 slipBps,uint256 deadline,uint256 cooldown,bool autoEnable) public onlyOwner {
        IBiggiBuybackAgent B = IBiggiBuybackAgent(buybackAgent);
        if (path.length == 0) B.clearSwapPath(); else B.setSwapPath(path);
        B.setFallbacks(slipBps, deadline, cooldown);
        B.toggleAutoBuyback(autoEnable);
    }

    function setupDripLMCore() public onlyOwner {
        IBiggiDripLiquidityManager D = IBiggiDripLiquidityManager(dripLM);
        D.setRouter(routerAddr); D.setReserve(reserveAddr); D.setDripDistributor(dripDistributor); D.setBuybackAgent(buybackAgent);
    }

    function configureDripLMParams(uint8 sellPct,uint256 slipBps,uint256 deadline) public onlyOwner {
        IBiggiDripLiquidityManager D = IBiggiDripLiquidityManager(dripLM);
        D.setSellPct(sellPct); D.setSlippageBps(slipBps); D.setTxDeadlineSec(deadline);
    }

    function setupDripDistributorCore(address treasury,uint256 tokensPerMint) public onlyOwner {
        require(treasury != address(0), "treasury=0");
        IDripDistributorSetup DD = IDripDistributorSetup(dripDistributor);
        DD.setTreasury(treasury); DD.setDripLM(dripLM); DD.setTokensPerMint(tokensPerMint);
    }

    function setSupplyTargets(address token_, address supplyController_) external onlyOwner {
        require(token_ != address(0), "token=0"); require(supplyController_ != address(0), "supply=0");
        tokenAddr = token_; supplyController = supplyController_; emit SupplyTargetsSet(token_, supplyController_);
    }

    function setupSupplyControllerCore() public onlyOwner {
        require(tokenAddr != address(0) && supplyController != address(0), "supply targets missing");
        IBiggiTokenSupplySetup(tokenAddr).setSupplyController(supplyController);
        emit SupplyControllerWired(tokenAddr, supplyController);
    }

    function configureSupplyControllerPair(address pair, bool snapshotBaseline_) public onlyOwner {
        require(supplyController != address(0), "supply=0"); require(pair != address(0), "pair=0");
        IBiggiSupplyControllerSetup(supplyController).setPair(pair);
        if (snapshotBaseline_) IBiggiSupplyControllerSetup(supplyController).snapshotBaseline();
        emit SupplyControllerPairConfigured(pair, snapshotBaseline_);
    }

    function runAll(address[] calldata buybackPath,uint256 buybackSlipBps,uint256 buybackDeadline,uint256 buybackCooldown,bool autoEnable,uint8 dripSellPct,uint256 dripSlippage,uint256 dripDeadline,address treasuryForDrip,uint256 tokensPerMint) external onlyOwner {
        require(!executed, "already executed");
        setupBuybackCore();
        configureBuybackSwapAndFallbacks(buybackPath, buybackSlipBps, buybackDeadline, buybackCooldown, autoEnable);
        setupDripLMCore();
        configureDripLMParams(dripSellPct, dripSlippage, dripDeadline);
        setupDripDistributorCore(treasuryForDrip, tokensPerMint);
        executed = true;
        emit BranchSetupExecuted(buybackAgent, dripLM, dripDistributor);
    }

    function runAllAndWireSupply(address[] calldata buybackPath,uint256 buybackSlipBps,uint256 buybackDeadline,uint256 buybackCooldown,bool autoEnable,uint8 dripSellPct,uint256 dripSlippage,uint256 dripDeadline,address treasuryForDrip,uint256 tokensPerMint,address tokenForSupply,address supplyController_,address pairForSupply,bool snapshotSupplyBaseline) external onlyOwner {
        require(!executed, "already executed");
        tokenAddr = tokenForSupply; supplyController = supplyController_; emit SupplyTargetsSet(tokenForSupply, supplyController_);
        setupBuybackCore();
        configureBuybackSwapAndFallbacks(buybackPath, buybackSlipBps, buybackDeadline, buybackCooldown, autoEnable);
        setupDripLMCore();
        configureDripLMParams(dripSellPct, dripSlippage, dripDeadline);
        setupDripDistributorCore(treasuryForDrip, tokensPerMint);
        setupSupplyControllerCore();
        if (pairForSupply != address(0)) configureSupplyControllerPair(pairForSupply, snapshotSupplyBaseline);
        executed = true;
        emit BranchSetupExecuted(buybackAgent, dripLM, dripDistributor);
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

// Minimal view interfaces
interface IBuybackAgentView {
    function autoBuybackEnabled() external view returns (bool);
    function paused() external view returns (bool);
    function router() external view returns (address);
    function wrappedNative() external view returns (address);
    function treasury() external view returns (address);
    function policy() external view returns (address);
    function dripLM() external view returns (address);
    function keeper() external view returns (address);
    function lastBuybackAt() external view returns (uint256);
    function totalNativeReceived() external view returns (uint256);
    function totalNativeSpent() external view returns (uint256);
    function totalBiggiAcquired() external view returns (uint256);
    function nativeBalance() external view returns (uint256);
    function biggiBalance() external view returns (uint256);
}

interface ITreasuryView {
    function polBalance() external view returns (uint256);
    function biggiBalance() external view returns (uint256);
    function totalPolReceivedFromDistributor() external view returns (uint256);
    function totalBiggiReceivedFromBuyback() external view returns (uint256);
}

interface IPolicyView {
    function swapSlippageBps() external view returns (uint256);
    function txDeadlineSec() external view returns (uint256);
    function minBuybackInterval() external view returns (uint256);
    function buybacksPaused() external view returns (bool);
    function maxDailyBuybackNative() external view returns (uint256);
    function usedToday() external view returns (uint256);
    function dayIndex() external view returns (uint64);
}

interface IBuybackKeeperProxyView {
    function minNativeThresholdWei() external view returns (uint256);
    function paused() external view returns (bool);
    function allowedCaller() external view returns (address);
    function agent() external view returns (IBuybackAgentView);
}

/**
 * @title BiggiBuybackReader
 * @notice Read-only agregátor pro FE/monitoring — žádné settery, žádné změny stavu.
 */
contract BiggiBuybackReader {
    IBuybackAgentView public immutable agent;
    ITreasuryView public immutable treasury;
    IPolicyView public immutable policy;
    IBuybackKeeperProxyView public immutable keeperProxy; // optional, může být address(0)

    constructor(address agent_, address treasury_, address policy_, address keeperProxy_) {
        require(agent_ != address(0) && treasury_ != address(0), "zero addr");
        agent = IBuybackAgentView(agent_);
        treasury = ITreasuryView(treasury_);
        policy = IPolicyView(policy_);
        keeperProxy = keeperProxy_ == address(0) ? IBuybackKeeperProxyView(address(0)) : IBuybackKeeperProxyView(keeperProxy_);
    }

    struct AgentSnapshot {
        bool autoBuybackEnabled;
        bool paused;
        address router;
        address wrappedNative;
        address treasury;
        address policy;
        address dripLM;
        address keeper;
        uint256 lastBuybackAt;
        uint256 totalNativeReceived;
        uint256 totalNativeSpent;
        uint256 totalBiggiAcquired;
        uint256 nativeBalance;
        uint256 biggiBalance;
    }

    struct TreasurySnapshot {
        uint256 polBalance;
        uint256 biggiBalance;
        uint256 totalPolReceived;
        uint256 totalBiggiReceived;
    }

    struct PolicySnapshot {
        uint256 swapSlippageBps;
        uint256 txDeadlineSec;
        uint256 minBuybackInterval;
        bool buybacksPaused;
        uint256 maxDailyBuybackNative;
        uint256 usedToday;
        uint64 dayIndex;
    }

    struct KeeperProxySnapshot {
        uint256 minNativeThresholdWei;
        bool paused;
        address allowedCaller;
        address agent;
    }

    function snapshot() external view returns (
        AgentSnapshot memory a,
        TreasurySnapshot memory t,
        PolicySnapshot memory p,
        KeeperProxySnapshot memory k
    ) {
        a.treasury = address(treasury);
        a.policy = address(policy);
        if (address(agent) != address(0)) {
            try agent.autoBuybackEnabled() returns (bool v) { a.autoBuybackEnabled = v; } catch {}
            try agent.paused() returns (bool v) { a.paused = v; } catch {}
            try agent.router() returns (address v) { a.router = v; } catch {}
            try agent.wrappedNative() returns (address v) { a.wrappedNative = v; } catch {}
            try agent.treasury() returns (address v) { a.treasury = v; } catch {}
            try agent.policy() returns (address v) { a.policy = v; } catch {}
            try agent.dripLM() returns (address v) { a.dripLM = v; } catch {}
            try agent.keeper() returns (address v) { a.keeper = v; } catch {}
            try agent.lastBuybackAt() returns (uint256 v) { a.lastBuybackAt = v; } catch {}
            try agent.totalNativeReceived() returns (uint256 v) { a.totalNativeReceived = v; } catch {}
            try agent.totalNativeSpent() returns (uint256 v) { a.totalNativeSpent = v; } catch {}
            try agent.totalBiggiAcquired() returns (uint256 v) { a.totalBiggiAcquired = v; } catch {}
            try agent.nativeBalance() returns (uint256 v) { a.nativeBalance = v; } catch {}
            try agent.biggiBalance() returns (uint256 v) { a.biggiBalance = v; } catch {}
        }

        if (address(treasury) != address(0)) {
            try treasury.polBalance() returns (uint256 v) { t.polBalance = v; } catch {}
            try treasury.biggiBalance() returns (uint256 v) { t.biggiBalance = v; } catch {}
            try treasury.totalPolReceivedFromDistributor() returns (uint256 v) { t.totalPolReceived = v; } catch {}
            try treasury.totalBiggiReceivedFromBuyback() returns (uint256 v) { t.totalBiggiReceived = v; } catch {}
        }

        if (address(policy) != address(0)) {
            try policy.swapSlippageBps() returns (uint256 v) { p.swapSlippageBps = v; } catch {}
            try policy.txDeadlineSec() returns (uint256 v) { p.txDeadlineSec = v; } catch {}
            try policy.minBuybackInterval() returns (uint256 v) { p.minBuybackInterval = v; } catch {}
            try policy.buybacksPaused() returns (bool v) { p.buybacksPaused = v; } catch {}
            try policy.maxDailyBuybackNative() returns (uint256 v) { p.maxDailyBuybackNative = v; } catch {}
            try policy.usedToday() returns (uint256 v) { p.usedToday = v; } catch {}
            try policy.dayIndex() returns (uint64 v) { p.dayIndex = v; } catch {}
        }

        k.agent = address(agent);
        if (address(keeperProxy) != address(0)) {
            try keeperProxy.minNativeThresholdWei() returns (uint256 v) { k.minNativeThresholdWei = v; } catch {}
            try keeperProxy.paused() returns (bool v) { k.paused = v; } catch {}
            try keeperProxy.allowedCaller() returns (address v) { k.allowedCaller = v; } catch {}
            try keeperProxy.agent() returns (IBuybackAgentView v) { k.agent = address(v); } catch {}
        }
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

/**
 * BiggiCommunityCenter
 *
 * Owner-curated grants + events (bez hlasování).
 * - Pool (rezerva) v kontraktu: distributor posílá share (depositFromDistributor / receiveMintShare)
 * - Owner vytvoří event s meta (title, ipfsHash, start, end) + totalPrize
 * - Owner při vytvoření eventu přiřadí winners[] a amounts[] (per-winner amounts)
 *   -> součet amounts musí rovnat totalPrize
 * - Při vytvoření se totalPrize "zamkne" z poolBalance (rezervováno pro event)
 * - Výherci volají claim(eventId) a obdrží svůj přidělený amount
 * - Žádné refundy/cancel (NE)
 * - Owner nemá admin-override nad claim statusy (NE)
 *
 * Low-risk vylepšení:
 * - Zero-address guard u setDistributor
 * - vlastní Donation event (receive už nelže “OwnerDeposit”)
 * - zákaz duplicitních winner adres v jednom eventu (eliminuje tichou nekonzistenci)
 * - totalLocked tracking (emergencyWithdraw už nemusí loopovat všechny eventy)
 * - sjednocení revertů na custom errors tam, kde to dává smysl
 * - drobné FE helper views (canClaim + userStatus) bez změny logiky
 */

import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "@openzeppelin/contracts/utils/Address.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

contract BiggiCommunityCenter is Ownable, ReentrancyGuard, Pausable {
    using Address for address payable;

    /* ------------ Events & Errors ------------ */
    event DistributorSet(address indexed oldDistributor, address indexed newDistributor);
    event DepositedFromDistributor(address indexed from, uint256 amount);
    event OwnerDeposit(address indexed from, uint256 amount);
    event DonationReceived(address indexed from, uint256 amount);

    event EventCreated(uint256 indexed eventId, string title, uint256 totalPrize);
    event WinnerAssigned(uint256 indexed eventId, address indexed winner, uint256 amount);
    event Claimed(uint256 indexed eventId, address indexed who, uint256 amount);

    event Rescue(address indexed to, uint256 amount);

    error NotDistributor();
    error ZeroAmount();
    error ZeroAddress();
    error BadLengths();
    error SumMismatch();
    error NotWinner();
    error AlreadyClaimed();
    error InsufficientPool();
    error EventNotExists();
    error DuplicateWinner();
    error TransferFailed();

    /* ------------ Storage ------------ */
    address public distributor; // distributor address (set by owner)

    uint256 public poolBalance; // POL available for new events (in wei)
    uint256 public totalLocked; // total locked across all events (avoids emergency loop)

    uint256 public nextEventId;

    struct EventInfo {
        string title;
        string ipfsHash;
        uint256 start;
        uint256 end;
        uint256 totalPrize; // requested total prize for event
        uint256 locked;     // how much currently locked / reserved for this event
        bool exists;
    }

    // eventId => EventInfo
    mapping(uint256 => EventInfo) public events;

    // eventId => winners array
    mapping(uint256 => address[]) private eventWinners;

    // eventId => winner => amount
    mapping(uint256 => mapping(address => uint256)) private eventAmounts;

    // eventId => winner => claimed
    mapping(uint256 => mapping(address => bool)) private eventClaimed;

    // list of all event ids
    uint256[] private allEventIds;

    /* ------------ Constructor ------------ */
    constructor(address initialOwner) Ownable(initialOwner) {
        nextEventId = 1;
    }

    /* ------------ Admin / Configuration ------------ */

    /// @notice set distributor address (owner)
    function setDistributor(address d) external onlyOwner {
        if (d == address(0)) revert ZeroAddress();
        address old = distributor;
        distributor = d;
        emit DistributorSet(old, d);
    }

    /// @notice deposit from Distributor (payable). Only distributor address can call.
    function depositFromDistributor() external payable whenNotPaused nonReentrant {
        if (msg.sender != distributor) revert NotDistributor();
        if (msg.value == 0) revert ZeroAmount();
        poolBalance += msg.value;
        emit DepositedFromDistributor(msg.sender, msg.value);
    }

    /// @notice compatibility: called by Distributor via selector receiveMintShare()
    function receiveMintShare() external payable whenNotPaused nonReentrant {
        if (msg.sender != distributor) revert NotDistributor();
        if (msg.value == 0) revert ZeroAmount();
        poolBalance += msg.value;
        emit DepositedFromDistributor(msg.sender, msg.value);
    }

    /// @notice owner can also top up pool manually
    function ownerDeposit() external payable onlyOwner whenNotPaused nonReentrant {
        if (msg.value == 0) revert ZeroAmount();
        poolBalance += msg.value;
        emit OwnerDeposit(msg.sender, msg.value);
    }

    /* ------------ Events management (owner) ------------ */

    function createEvent(
        string calldata title,
        string calldata ipfsHash,
        uint256 start,
        uint256 end,
        uint256 totalPrize,
        address[] calldata winners,
        uint256[] calldata amounts
    ) external onlyOwner whenNotPaused returns (uint256 eventId) {
        if (winners.length == 0 || winners.length != amounts.length) revert BadLengths();
        if (totalPrize == 0) revert ZeroAmount();

        // sum amounts
        uint256 s = 0;
        for (uint256 i = 0; i < amounts.length; ++i) {
            s += amounts[i];
        }
        if (s != totalPrize) revert SumMismatch();
        if (totalPrize > poolBalance) revert InsufficientPool();

        // reserve pool
        poolBalance -= totalPrize;
        totalLocked += totalPrize;

        eventId = nextEventId++;
        EventInfo storage e = events[eventId];
        e.title = title;
        e.ipfsHash = ipfsHash;
        e.start = start;
        e.end = end;
        e.totalPrize = totalPrize;
        e.locked = totalPrize;
        e.exists = true;

        // store winners + amounts
        for (uint256 i = 0; i < winners.length; ++i) {
            address w = winners[i];
            uint256 a = amounts[i];

            if (w == address(0)) revert ZeroAddress();
            if (a == 0) revert ZeroAmount();

            // prevent duplicates (otherwise mapping overwrite would cause silent inconsistency)
            if (eventAmounts[eventId][w] != 0) revert DuplicateWinner();

            eventWinners[eventId].push(w);
            eventAmounts[eventId][w] = a;

            emit WinnerAssigned(eventId, w, a);
        }

        allEventIds.push(eventId);
        emit EventCreated(eventId, title, totalPrize);
    }

    /* ------------ Claim (recipient withdraw) ------------ */

    /// @notice winner claims their amount for a given eventId
    function claim(uint256 eventId) external nonReentrant whenNotPaused {
        if (!events[eventId].exists) revert EventNotExists();

        uint256 amount = eventAmounts[eventId][msg.sender];
        if (amount == 0) revert NotWinner();
        if (eventClaimed[eventId][msg.sender]) revert AlreadyClaimed();

        // checks-effects-interactions
        eventClaimed[eventId][msg.sender] = true;

        EventInfo storage e = events[eventId];
        // sanity
        if (e.locked < amount) revert SumMismatch();

        e.locked -= amount;
        totalLocked -= amount;

        (bool ok, ) = payable(msg.sender).call{value: amount}("");
        if (!ok) revert TransferFailed();

        emit Claimed(eventId, msg.sender, amount);
    }

    /* ------------ Getters for frontend / indexers ------------ */

    /// @notice list of event ids (useful for FE)
    function getEvents() external view returns (uint256[] memory) {
        return allEventIds;
    }

    /// @notice basic event data
    function getEvent(uint256 eventId)
        external
        view
        returns (
            string memory title,
            string memory ipfsHash,
            uint256 start,
            uint256 end,
            uint256 totalPrize_,
            uint256 locked,
            bool exists
        )
    {
        EventInfo storage e = events[eventId];
        return (e.title, e.ipfsHash, e.start, e.end, e.totalPrize, e.locked, e.exists);
    }

    /// @notice winners + amounts + claimed flags
    function getEventWinners(uint256 eventId)
        external
        view
        returns (address[] memory winners, uint256[] memory amounts, bool[] memory claimed)
    {
        winners = eventWinners[eventId];
        amounts = new uint256[](winners.length);
        claimed = new bool[](winners.length);

        for (uint256 i = 0; i < winners.length; ++i) {
            address w = winners[i];
            amounts[i] = eventAmounts[eventId][w];
            claimed[i] = eventClaimed[eventId][w];
        }
    }

    /// @notice how much is locked for an event
    function balanceOfEvent(uint256 eventId) external view returns (uint256) {
        return events[eventId].locked;
    }

    /// @notice check payout assigned to an address (0 if none)
    function assignedAmountOf(uint256 eventId, address who) external view returns (uint256) {
        return eventAmounts[eventId][who];
    }

    /// @notice FE helper: user status for a given event
    function userStatus(uint256 eventId, address who) external view returns (uint256 amount, bool claimed, bool exists) {
        exists = events[eventId].exists;
        amount = eventAmounts[eventId][who];
        claimed = eventClaimed[eventId][who];
    }

    /// @notice FE helper: canClaim with reason codes
    /// reason: 0=OK, 1=EventNotExists, 2=NotWinner, 3=AlreadyClaimed, 4=Paused
    function canClaim(uint256 eventId, address who) external view returns (bool ok, uint8 reason, uint256 amount) {
        if (paused()) return (false, 4, 0);
        if (!events[eventId].exists) return (false, 1, 0);

        amount = eventAmounts[eventId][who];
        if (amount == 0) return (false, 2, 0);
        if (eventClaimed[eventId][who]) return (false, 3, amount);

        return (true, 0, amount);
    }

    /* ------------ Rescue / Admin helpers ------------ */

    /// @notice owner may rescue leftover pool funds (non-locked). Locked funds per event remain.
    function rescuePool(address payable to, uint256 amount) external onlyOwner whenNotPaused nonReentrant {
        if (to == address(0)) revert ZeroAddress();
        if (amount > poolBalance) revert InsufficientPool();
        poolBalance -= amount;
        to.sendValue(amount);
        emit Rescue(to, amount);
    }

    /// @notice emergency withdraw (owner) - sends entire contract balance that is not locked by events
    function emergencyWithdraw(address payable to) external onlyOwner whenPaused nonReentrant {
        if (to == address(0)) revert ZeroAddress();

        uint256 contractBal = address(this).balance;
        uint256 avail = contractBal > totalLocked ? (contractBal - totalLocked) : 0;
        require(avail > 0, "no avail");

        // keep poolBalance consistent: emergency withdraw should reduce free pool first
        if (avail >= poolBalance) {
            poolBalance = 0;
        } else {
            poolBalance -= avail;
        }

        to.sendValue(avail);
        emit Rescue(to, avail);
    }

    /* ------------ Pause / Unpause ------------ */
    function pause() external onlyOwner { _pause(); }
    function unpause() external onlyOwner { _unpause(); }

    /* ------------ Fallbacks ------------ */
    receive() external payable {
        if (msg.value == 0) return;

        poolBalance += msg.value;

        if (msg.sender == owner()) {
            emit OwnerDeposit(msg.sender, msg.value);
        } else if (msg.sender == distributor) {
            emit DepositedFromDistributor(msg.sender, msg.value);
        } else {
            emit DonationReceived(msg.sender, msg.value);
        }
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";

interface IUniswapV2PairGuard {
    function getReserves() external view returns (uint112 reserve0, uint112 reserve1, uint32 blockTimestampLast);
    function token0() external view returns (address);
    function token1() external view returns (address);
}

interface IBiggiSupplyControllerDex {
    function refillDex(uint256 amount) external;
}

interface IAggregatorLike {
    function latestAnswer() external view returns (int256);
}

contract BiggiDexReserveGuard is Ownable, ReentrancyGuard, Pausable {
    error ZeroAddress();
    error CooldownActive();
    error BaselineNotSet();
    error ReserveHealthy();
    error NotKeeper();
    error OraclePriceInvalid();
    error PriceDeviationTooHigh();

    address public pair;
    address public token;
    address public quoteToken;
    IBiggiSupplyControllerDex public supplyController;
    IAggregatorLike public quoteOracle;

    mapping(address => bool) public keepers;

    uint256 public baselineReserve;
    uint256 public minReserveRatioBps = 5000;
    uint256 public refillAmount = 20_000_000e18;
    uint256 public cooldown = 30 minutes;
    uint256 public lastRefillAt;
    bool public autoRefreshBaselineOnRefill = true;

    bool public priceCheckEnabled;
    uint256 public maxPriceDeviationBps = 2000;
    uint256 public lastGoodDexPriceE18;

    event KeeperSet(address indexed keeper, bool allowed);
    event PairSet(address indexed pair);
    event QuoteOracleSet(address indexed oracle);
    event BaselineSnapshotted(uint256 reserve);
    event RefillTriggered(uint256 reserveNow, uint256 baselineReserve, uint256 refillAmount, uint256 timestamp);
    event PriceCheckConfigSet(bool enabled, uint256 maxDeviationBps);
    event CooldownSet(uint256 cooldownSec);
    event RefillAmountSet(uint256 amount);
    event ReserveRatioSet(uint256 ratioBps);
    event AutoRefreshBaselineSet(bool enabled);

    constructor(address initialOwner,address pair_,address token_,address quoteToken_,address supplyController_) Ownable(initialOwner) {
        if (initialOwner == address(0) || pair_ == address(0) || token_ == address(0) || quoteToken_ == address(0) || supplyController_ == address(0)) revert ZeroAddress();
        pair = pair_;
        token = token_;
        quoteToken = quoteToken_;
        supplyController = IBiggiSupplyControllerDex(supplyController_);
    }

    function setKeeper(address keeper, bool allowed) external onlyOwner { keepers[keeper] = allowed; emit KeeperSet(keeper, allowed); }
    function setPair(address pair_) external onlyOwner { if (pair_ == address(0)) revert ZeroAddress(); pair = pair_; emit PairSet(pair_); }
    function setQuoteOracle(address oracle_) external onlyOwner { quoteOracle = IAggregatorLike(oracle_); emit QuoteOracleSet(oracle_); }
    function setReserveRatioBps(uint256 ratioBps) external onlyOwner { require(ratioBps > 0 && ratioBps <= 10_000, "bad bps"); minReserveRatioBps = ratioBps; emit ReserveRatioSet(ratioBps); }
    function setRefillAmount(uint256 amount) external onlyOwner { require(amount > 0, "amount=0"); refillAmount = amount; emit RefillAmountSet(amount); }
    function setCooldown(uint256 cooldownSec) external onlyOwner { cooldown = cooldownSec; emit CooldownSet(cooldownSec); }
    function setAutoRefreshBaselineOnRefill(bool enabled) external onlyOwner { autoRefreshBaselineOnRefill = enabled; emit AutoRefreshBaselineSet(enabled); }
    function setPriceCheckConfig(bool enabled, uint256 deviationBps) external onlyOwner { require(deviationBps <= 10_000, "bad bps"); priceCheckEnabled = enabled; maxPriceDeviationBps = deviationBps; emit PriceCheckConfigSet(enabled, deviationBps); }
    function pause() external onlyOwner { _pause(); }
    function unpause() external onlyOwner { _unpause(); }

    function snapshotBaseline() public onlyOwner {
        uint256 reserve_ = currentTokenReserve();
        require(reserve_ > 0, "reserve=0");
        baselineReserve = reserve_;
        emit BaselineSnapshotted(reserve_);
    }

    function refreshPriceAnchor() external onlyOwner {
        uint256 dexPrice = currentDexPriceE18();
        if (dexPrice == 0) revert OraclePriceInvalid();
        lastGoodDexPriceE18 = dexPrice;
    }

    function currentTokenReserve() public view returns (uint256) {
        IUniswapV2PairGuard p = IUniswapV2PairGuard(pair);
        (uint112 r0, uint112 r1,) = p.getReserves();
        return p.token0() == token ? uint256(r0) : uint256(r1);
    }

    function currentQuoteReserve() public view returns (uint256) {
        IUniswapV2PairGuard p = IUniswapV2PairGuard(pair);
        (uint112 r0, uint112 r1,) = p.getReserves();
        return p.token0() == token ? uint256(r1) : uint256(r0);
    }

    function currentDexPriceE18() public view returns (uint256) {
        uint256 reserveToken = currentTokenReserve();
        uint256 reserveQuote = currentQuoteReserve();
        if (reserveToken == 0) return 0;
        return (reserveQuote * 1e18) / reserveToken;
    }

    function minAllowedReserve() public view returns (uint256) { return (baselineReserve * minReserveRatioBps) / 10_000; }

    function refillNeeded() public view returns (bool needed, string memory reason) {
        if (paused()) return (false, "paused");
        if (baselineReserve == 0) return (false, "baseline not set");
        if (block.timestamp < lastRefillAt + cooldown) return (false, "cooldown");
        if (currentTokenReserve() >= minAllowedReserve()) return (false, "reserve healthy");
        return (true, "reserve depleted");
    }

    function checkUpkeep(bytes calldata) external view returns (bool upkeepNeeded, bytes memory performData) {
        (bool needed,) = refillNeeded();
        upkeepNeeded = needed;
        performData = abi.encode(refillAmount);
    }

    function performUpkeep(bytes calldata performData) external whenNotPaused nonReentrant {
        if (!(keepers[msg.sender] || msg.sender == owner())) revert NotKeeper();
        uint256 amount = abi.decode(performData, (uint256));
        _refillDex(amount);
    }

    function manualRefillDex() external onlyOwner whenNotPaused nonReentrant { _refillDex(refillAmount); }

    function _refillDex(uint256 amount) internal {
        if (baselineReserve == 0) revert BaselineNotSet();
        if (block.timestamp < lastRefillAt + cooldown) revert CooldownActive();
        uint256 reserveNow = currentTokenReserve();
        if (reserveNow >= minAllowedReserve()) revert ReserveHealthy();
        if (priceCheckEnabled) _enforcePriceSanity();
        supplyController.refillDex(amount);
        lastRefillAt = block.timestamp;
        if (autoRefreshBaselineOnRefill) { baselineReserve = currentTokenReserve(); emit BaselineSnapshotted(baselineReserve); }
        emit RefillTriggered(reserveNow, baselineReserve, amount, block.timestamp);
    }

    function _enforcePriceSanity() internal view {
        uint256 dexPrice = currentDexPriceE18();
        if (dexPrice == 0) revert OraclePriceInvalid();
        if (address(quoteOracle) != address(0)) { int256 quoteAnswer = quoteOracle.latestAnswer(); if (quoteAnswer <= 0) revert OraclePriceInvalid(); }
        if (lastGoodDexPriceE18 == 0) return;
        uint256 higher = dexPrice > lastGoodDexPriceE18 ? dexPrice : lastGoodDexPriceE18;
        uint256 lower = dexPrice > lastGoodDexPriceE18 ? lastGoodDexPriceE18 : dexPrice;
        uint256 deviationBps = ((higher - lower) * 10_000) / lower;
        if (deviationBps > maxPriceDeviationBps) revert PriceDeviationTooHigh();
    }
}

