        string symbol_;
        uint8 decimals_;
    }

    struct RewardsStatus {
        address tokenRewards;
        address token;
        address main;
        address main2;
        uint256 unitReward;
        uint8[11] blockWeights;
        uint256 rewardsCap;
        uint256 rewardsMinted;
        uint256 rewardsCapRemaining;
        uint256 tokenRemainingMintable;
        uint256 rewardBalance;
        uint256 totalDistributed;
        uint256 distributedThisWeek;
        uint256 lastWeekDistributed;
        uint64 currentWeek;
        uint64 lastRecordedWeek;
    }

    IBiggiTokenRewards public immutable tokenRewards;

    constructor(address tokenRewards_) {
        require(tokenRewards_ != address(0), "zero");
        tokenRewards = IBiggiTokenRewards(tokenRewards_);
    }

    function getStatus() external view returns (RewardsStatus memory s, TokenMeta memory meta) {
        address tokenAddr = tokenRewards.biggi();
        IERC20Metadata token = IERC20Metadata(tokenAddr);

        s.tokenRewards = address(tokenRewards);
        s.token = tokenAddr;
        s.main = tokenRewards.mainNFT();
        s.main2 = tokenRewards.main2NFT();
        s.unitReward = tokenRewards.unitReward();
        s.blockWeights = tokenRewards.getBlockWeights();
        s.rewardsCap = tokenRewards.rewardsCap();
        s.rewardsMinted = tokenRewards.rewardsMinted();
        s.rewardsCapRemaining = tokenRewards.rewardsCapRemaining();
        s.tokenRemainingMintable = tokenRewards.tokenRemainingMintable();
        s.rewardBalance = token.balanceOf(address(tokenRewards));
        s.totalDistributed = tokenRewards.totalDistributed();
        s.distributedThisWeek = tokenRewards.distributedThisWeek();
        s.lastWeekDistributed = tokenRewards.lastWeekDistributed();
        s.currentWeek = tokenRewards.currentWeek();
        s.lastRecordedWeek = tokenRewards.lastRecordedWeek();

        (meta.name_, meta.symbol_, meta.decimals_) = tokenRewards.tokenMeta();
    }

    function getBlockWeights() external view returns (uint8[11] memory w) {
        return tokenRewards.getBlockWeights();
    }

    function getTokenMeta() external view returns (TokenMeta memory meta) {
        (meta.name_, meta.symbol_, meta.decimals_) = tokenRewards.tokenMeta();
    }

    function preview(uint256[] calldata tokenIds) external view returns (uint256 units, uint256 amount) {
        return tokenRewards.claimablePreview(tokenIds);
    }

    function previewFor(address[] calldata collections, uint256[] calldata tokenIds)
        external
        view
        returns (uint256 units, uint256 amount)
    {
        return tokenRewards.claimablePreviewFor(collections, tokenIds);
    }

    function nextClaimWeekFor(uint256 tokenId) external view returns (uint64) {
        return tokenRewards.nextClaimWeekFor(tokenId);
    }

    function nextClaimWeekForCollection(address collection, uint256 tokenId) external view returns (uint64) {
        return tokenRewards.nextClaimWeekForCollection(collection, tokenId);
    }

    function isAllowedCollection(address coll) external view returns (bool) {
        return tokenRewards.isAllowedCollection(coll);
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "./Library/BiggiBpsLib.sol";
import "./Library/BiggiErrorsLib.sol";

interface IBiggiDripDistributorDeposit {
    function depositTokens(uint256 amount) external;
}

/**
 * BiggiTreasury — final
 * - přijímá BIGGI z BuybackAgent (agent approve -> treasury.buybackDepositAndSplit(amount))
 * - treasury provede safeTransferFrom(msg.sender, this, amount) (pull)
 * - rozdělí přijaté BIGGI: 34% -> tokenRewards, 33% -> reserveAddr, 33% -> dripDistributor
 * - přijímá POL z Distributora přes depositPolFromDistributor() a drží ho jako emergency
 */
contract BiggiTreasury is Ownable {
    using SafeERC20 for IERC20;

    IERC20 public immutable BIGGI;

    address public distributor;      // adresa Distributor kontraktu (posílá POL)
    address public buybackAgent;     // buyback zavolá buybackDepositAndSplit
    address public tokenRewards;     // příjemce 34%
    address public reserveAddr;      // příjemce 33%
    address public dripDistributor;  // příjemce 33%

    uint256 public totalBiggiReceived;
    uint256 public totalPolReceived;
    bool public historicalTotalsSeeded;

    event DistributorSet(address indexed oldAddr, address indexed newAddr);
    event BuybackAgentSet(address indexed oldAddr, address indexed newAddr);
    event TokenRewardsSet(address indexed oldAddr, address indexed newAddr);
    event ReserveSet(address indexed oldAddr, address indexed newAddr);
    event DripDistributorSet(address indexed oldAddr, address indexed newAddr);
    event BuybackReceived(uint256 amount, uint256 toRewards, uint256 toReserve, uint256 toDrip);
    event PolFromDistributor(uint256 amount, uint256 totalReceived);
    event HistoricalTotalsSeeded(uint256 totalBiggiReceived, uint256 totalPolReceived);

    constructor(address biggiToken, address initialOwner) Ownable(initialOwner) {
        if (biggiToken == address(0) || initialOwner == address(0)) {
            revert BiggiErrorsLib.ZeroAddress();
        }
        BIGGI = IERC20(biggiToken);
    }

    /* ===== Settery (onlyOwner) ===== */
    function setDistributor(address d) external onlyOwner {
        emit DistributorSet(distributor, d);
        distributor = d;
    }

    function setBuybackAgent(address b) external onlyOwner {
        emit BuybackAgentSet(buybackAgent, b);
        buybackAgent = b;
    }

    function setTokenRewards(address r) external onlyOwner {
        emit TokenRewardsSet(tokenRewards, r);
        tokenRewards = r;
    }

    function setReserve(address r) external onlyOwner {
        emit ReserveSet(reserveAddr, r);
        reserveAddr = r;
    }

    function setDripDistributor(address d) external onlyOwner {
        emit DripDistributorSet(dripDistributor, d);
        dripDistributor = d;
    }

    function seedHistoricalTotals(uint256 biggiReceived_, uint256 polReceived_) external onlyOwner {
        require(!historicalTotalsSeeded, "already seeded");
        totalBiggiReceived = biggiReceived_;
        totalPolReceived = polReceived_;
        historicalTotalsSeeded = true;
        emit HistoricalTotalsSeeded(biggiReceived_, polReceived_);
    }

    /* ===== Inflow POL z Distributoru (10% podíl apod.) =====
           Distributor musí volat tuto funkci. POL zůstanou v treasury. */
    function depositPolFromDistributor() external payable {
        _recordPolFromDistributor();
    }

    function receiveMintShare() external payable {
        _recordPolFromDistributor();
    }

    function _recordPolFromDistributor() internal {
        if (msg.sender != distributor) revert BiggiErrorsLib.NotDistributor();
        if (msg.value == 0) revert BiggiErrorsLib.AmountZero();
        totalPolReceived += msg.value;
        emit PolFromDistributor(msg.value, totalPolReceived);
    }

    /* ===== Inflow BIGGI z BuybackAgent =====
       BuybackAgent nejprve approve(treasury, amount) a poté zavolá buybackDepositAndSplit(amount).
       Treasury PULLne tokeny pomocí safeTransferFrom(msg.sender, this, amount) a rozdělí je.
    */
    function buybackDepositAndSplit(uint256 amount) external {
        if (msg.sender != buybackAgent) revert BiggiErrorsLib.NotBuybackAgent();
        if (amount == 0) revert BiggiErrorsLib.AmountZero();

        // Pull tokeny z buyback agenta (musí mít allowance)
        BIGGI.safeTransferFrom(msg.sender, address(this), amount);

        _splitBuybackBiggi(amount);
    }

    function ownerDepositAndSplit(uint256 amount) external onlyOwner {
        if (amount == 0) revert BiggiErrorsLib.AmountZero();
        BIGGI.safeTransferFrom(msg.sender, address(this), amount);
        _splitBuybackBiggi(amount);
    }

    function _splitBuybackBiggi(uint256 amount) internal {

        // účetnictví
        totalBiggiReceived += amount;

        // vypočítat části přes BiggiBpsLib.part (34 % / 33 % / 33 %)
        uint256 partRewards = BiggiBpsLib.part(amount, 3400); // 34%
        uint256 partReserve = BiggiBpsLib.part(amount, 3300); // 33%
        uint256 partDrip    = amount - partRewards - partReserve; // zbytek (cca 33% +/- zaokrouhlení)

        // pokusit se rozeslat, pokud jsou cíle nastaveny; jinak ponechat v kontraktu
        if (tokenRewards != address(0) && partRewards > 0) {
            BIGGI.safeTransfer(tokenRewards, partRewards);
        }
        if (reserveAddr != address(0) && partReserve > 0) {
            BIGGI.safeTransfer(reserveAddr, partReserve);
        }
        if (dripDistributor != address(0) && partDrip > 0) {
            _approveToken(dripDistributor, partDrip);
            IBiggiDripDistributorDeposit(dripDistributor).depositTokens(partDrip);
        }

        emit BuybackReceived(amount, partRewards, partReserve, partDrip);
    }

    function _approveToken(address spender, uint256 amount) internal {
        (bool ok0, bytes memory d0) = address(BIGGI).call(
            abi.encodeWithSelector(IERC20.approve.selector, spender, 0)
        );
        require(ok0 && (d0.length == 0 || abi.decode(d0, (bool))), "approve0 failed");

        (bool ok1, bytes memory d1) = address(BIGGI).call(
            abi.encodeWithSelector(IERC20.approve.selector, spender, amount)
        );
        require(ok1 && (d1.length == 0 || abi.decode(d1, (bool))), "approve failed");
    }

    /* ===== Views pro frontend / audit ===== */
    function biggiBalance() external view returns (uint256) {
        return BIGGI.balanceOf(address(this));
    }

    function polBalance() external view returns (uint256) {
        return address(this).balance;
    }

    function totalBiggiReceivedFromBuyback() external view returns (uint256) {
        return totalBiggiReceived;
    }

    function totalPolReceivedFromDistributor() external view returns (uint256) {
        return totalPolReceived;
    }

    /* ===== Rescue (owner) ===== */
    function rescueERC20(address token, address to, uint256 amount) external onlyOwner {
        if (to == address(0)) revert BiggiErrorsLib.ZeroAddress();
        IERC20(token).safeTransfer(to, amount);
    }

    function rescueETH(address payable to, uint256 amount) external onlyOwner {
        if (to == address(0)) revert BiggiErrorsLib.ZeroAddress();
        (bool ok, ) = to.call{value: amount}("");
        require(ok, "rescue failed");
    }

    receive() external payable {}
    fallback() external payable {}
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

/**
 * BiggiBuybackUpkeepProxy (OZ Ownable(initialOwner))
 * - Proxy pro Chainlink Automation (keeper) k volání buybackAgenta.
 * - checkUpkeep: ověří lokální paused, existence agenta, threshold, policy a cooldown.
 * - performUpkeep: bezpečně zavolá agent.buybackAllToTreasury(0) v try/catch, proxy nezarevertuje při chybě agenta.
 */

import "@openzeppelin/contracts/access/Ownable.sol";

interface IBiggiPolicy {
    function buybacksPaused() external view returns (bool);
    function minBuybackInterval() external view returns (uint256);
}

interface IBiggiBuybackAgent {
    function policy() external view returns (IBiggiPolicy);
    function lastBuybackAt() external view returns (uint256);
    function buybackAllToTreasury(uint256 minOut) external;
    function nativeBalance() external view returns (uint256); // view helper (preferred)
}

interface AutomationCompatibleInterface {
    function checkUpkeep(bytes calldata) external view returns (bool upkeepNeeded, bytes memory performData);
    function performUpkeep(bytes calldata) external;
}

contract BiggiBuybackUpkeepProxy is AutomationCompatibleInterface, Ownable {
    // --- state ---
    IBiggiBuybackAgent public agent;
    uint256 public minNativeThresholdWei; // např. 1e18 = 1 POL
    bool public paused;

    // --- events ---
    event AgentSet(address indexed agent);
    event ThresholdSet(uint256 weiAmount);
    event PausedSet(bool paused);
    event Performed(bool success, uint256 nativeBalanceAtCall);
    event PerformFailed(string reason);

    // Deploy s ownerem (multisig) => Ownable(initialOwner)
    constructor(address initialOwner) Ownable(initialOwner) {}

    // --- admin ---
    function setAgent(address a) external onlyOwner {
        require(a != address(0), "ZERO_AGENT");
        agent = IBiggiBuybackAgent(a);
        emit AgentSet(a);
    }
    function setThreshold(uint256 t) external onlyOwner {
        require(t > 0, "THRESHOLD_ZERO");
        minNativeThresholdWei = t;
        emit ThresholdSet(t);
    }
    function setPaused(bool p) external onlyOwner {
        paused = p;
        emit PausedSet(p);
    }

    // --- automation ---
    function checkUpkeep(bytes calldata)
        external
        view
        override
        returns (bool upkeepNeeded, bytes memory performData)
    {
        if (paused) return (false, bytes("PAUSED_LOCAL"));
        if (address(agent) == address(0)) return (false, bytes("NO_AGENT"));
        if (minNativeThresholdWei == 0) return (false, bytes("NO_THRESHOLD"));

        // policy checks via agent
        IBiggiPolicy pol = agent.policy();
        if (address(pol) == address(0)) return (false, bytes("NO_POLICY"));
        if (pol.buybacksPaused()) return (false, bytes("PAUSED_POLICY"));

        uint256 last = agent.lastBuybackAt();
        uint256 cool = pol.minBuybackInterval();
        if (cool > 0 && last != 0 && block.timestamp < last + cool) {
            return (false, bytes("COOLDOWN"));
        }

        // preferovaný check přes agent.nativeBalance() pokud implementováno
        uint256 nativeBal = agent.nativeBalance();
        if (nativeBal < minNativeThresholdWei) return (false, bytes("LOW_BALANCE"));

        // pokud vše OK, do performData vracíme adresu agenta a threshold (keeper může použít)
        return (true, abi.encode(address(agent), minNativeThresholdWei));
    }

    function performUpkeep(bytes calldata /* performData */) external override {
        if (paused) {
            emit PerformFailed("PAUSED_LOCAL");
            return;
        }
        if (address(agent) == address(0)) {
            emit PerformFailed("NO_AGENT_AT_PERFORM");
            return;
        }
        if (minNativeThresholdWei == 0) {
            emit PerformFailed("NO_THRESHOLD_AT_PERFORM");
            return;
        }

        uint256 nativeBal = agent.nativeBalance();

        if (nativeBal < minNativeThresholdWei) {
            emit PerformFailed("LOW_BALANCE_AT_PERFORM");
            return;
        }

        // bezpečné volání: pokud agent revertne, proxy nezarevertuje a jen zaloguje
        try agent.buybackAllToTreasury(0) {
            emit Performed(true, nativeBal);
        } catch Error(string memory reason) {
            emit PerformFailed(reason);
            emit Performed(false, nativeBal);
        } catch {
            emit PerformFailed("BUYBACK_CALL_REVERT");
            emit Performed(false, nativeBal);
        }
    }
}

